//! The index the real `kanso-themes` builder publishes parses under the rules
//! Kanso applies. The fixture is generated by `node scripts/gallery.mjs`;
//! this test catches a builder that stops writing a field Kanso requires
//! (the icon preview pins once lost their `size`).

use semver::Version;
use serde_json::Value;

const FIXTURE: &[u8] = include_bytes!("fixtures/builder-index.json");

fn index() -> kanso_gallery::Index {
    serde_json::from_slice(FIXTURE).expect("the builder's index parses")
}

#[test]
fn the_builders_index_parses_and_validates() {
    let value: Value = serde_json::from_slice(FIXTURE).unwrap();
    let themes = value["themes"].as_array().expect("themes");
    assert!(!themes.is_empty());
    let mut previews = 0;
    for theme in themes {
        let pins: Vec<&Value> = ["file", "bundle"]
            .into_iter()
            .filter_map(|key| theme.get(key))
            .chain(theme["preview"].as_array().into_iter().flatten())
            .collect();
        for pin in pins {
            assert!(
                pin["size"].as_u64().is_some_and(|size| size > 0),
                "{} names a file without a real size",
                theme["id"]
            );
            assert!(
                pin["sha256"].as_str().is_some_and(|sha| sha.len() == 64),
                "{} names a file without a SHA-256",
                theme["id"]
            );
        }
        previews += theme["preview"].as_array().map_or(0, Vec::len);
    }
    assert!(previews > 0, "the builder publishes icon previews");

    let index = index();
    index
        .check(&Version::new(0, 9, 0))
        .expect("the builder's index passes every catalogue rule");
}

#[test]
fn a_preview_without_a_size_is_refused() {
    let mut value: Value = serde_json::from_slice(FIXTURE).unwrap();
    let icon = value["themes"]
        .as_array_mut()
        .unwrap()
        .iter_mut()
        .find(|theme| theme["kind"] == "icons" && !theme["preview"].as_array().unwrap().is_empty())
        .expect("an icon theme with previews");
    icon["preview"][0].as_object_mut().unwrap().remove("size");
    let bytes = serde_json::to_vec(&value).unwrap();
    assert!(
        serde_json::from_slice::<kanso_gallery::Index>(&bytes).is_err(),
        "FileRef requires size"
    );
}

#[test]
fn the_builders_index_verifies_against_a_shipped_style_key() {
    // A key made inside the test, never the owner's.
    let (key, _) = kanso_update::feed::generate_signing_key();
    let signature = kanso_update::sign_feed(FIXTURE, &key).into_bytes();
    let index = kanso_gallery::check_index(
        FIXTURE,
        &signature,
        &[key.verifying_key()],
        &kanso_gallery::Floor::default(),
        &Version::new(0, 9, 0),
    )
    .expect("signed builder output verifies");
    assert!(!index.themes.is_empty());
}
